## FIX 1 â€” `/api/vocab/add` must seed the SRS schedule

**Target:** `handleVocabAdd` at [index.js:3573](APPS/NET-PET-AI/src/index.js#L3573). It already imports `computeNextReview` (line 16). Make every added word immediately due.

Replace the body so that after writing `vocab_list_`, it ALSO writes `srs_data_`:

```javascript
async function handleVocabAdd(body, env) {
  const studentId = body.studentId || "anonymous";
  const idCheck = validateStudentId(studentId);
  if (!idCheck.valid) return json({ error: idCheck.error }, 400);
  if (!body.word?.trim()) return json({ error: "word required" }, 400);
  const word = body.word.trim();

  const [listRaw, srsRaw] = await Promise.all([
    env.NET_PET_KV.get(`vocab_list_${studentId}`),
    env.NET_PET_KV.get(`srs_data_${studentId}`)
  ]);
  const list = listRaw ? JSON.parse(listRaw) : [];
  if (!list.find(w => w.word === word)) {
    list.push({ word, meaning_vi: body.meaning_vi || "", ts: Date.now() });
  }
  // Seed SRS: new class word is due NOW (next_review = 0) so OBI drills it next session
  const srsMap = srsRaw ? JSON.parse(srsRaw) : {};
  if (!srsMap[word]) {
    srsMap[word] = { word, translation: body.meaning_vi || "", interval: 0, repetitions: 0, ease_factor: 2.5, next_review: 0, last_grade: null };
  }
  await Promise.all([
    env.NET_PET_KV.put(`vocab_list_${studentId}`, JSON.stringify(list.slice(-500))),
    env.NET_PET_KV.put(`srs_data_${studentId}`, JSON.stringify(srsMap))
  ]);
  return json({ ok: true, word, due: true });
}
```

## FIX 2 â€” `/api/vocab/due` must read the canonical store

**Target:** `handleVocabDue` at [index.js:3583](APPS/NET-PET-AI/src/index.js#L3583). Kill the `srs:id:due` orphan read. Read `srs_data_`, filter `next_review <= now`, enrich with meanings from `vocab_list_`.

```javascript
async function handleVocabDue(studentId, env) {
  if (!studentId) return json({ due: [], count: 0 });
  if (studentId.startsWith('sov100-test-')) return json({ due: [], count: 0 });
  const idCheck = validateStudentId(studentId);
  if (!idCheck.valid) return json({ error: idCheck.error }, 400);
  try {
    const [srsRaw, listRaw] = await Promise.all([
      env.NET_PET_KV.get(`srs_data_${studentId}`),
      env.NET_PET_KV.get(`vocab_list_${studentId}`)
    ]);
    if (!srsRaw) return json({ due: [], count: 0 });
    const srsMap = JSON.parse(srsRaw);
    const meanings = {};
    if (listRaw) for (const w of JSON.parse(listRaw)) meanings[w.word] = w.meaning_vi || "";
    const now = Date.now();
    const due = Object.values(srsMap)
      .filter(w => (w.next_review ?? 0) <= now)
      .sort((a, b) => (a.next_review ?? 0) - (b.next_review ?? 0))
      .map(w => ({ word: w.word, translation: w.translation || meanings[w.word] || "" }));
    return json({ due, count: due.length });
  } catch (err) {
    logWarn('VOCAB_DUE_KV_FAIL', { studentId, error: err.message }, env);
    return json({ due: [], count: 0 });
  }
}
```

## FIX 3 â€” `/api/vocab/review` must use SM-2 + write the canonical store

**Target:** `handleVocabReview` at [index.js:3604](APPS/NET-PET-AI/src/index.js#L3604). Replace the homegrown exponential with `computeNextReview`, write back into the `srs_data_` map.

```javascript
async function handleVocabReview(body, env) {
  const studentId = body.studentId || "anonymous";
  const idCheck = validateStudentId(studentId);
  if (!idCheck.valid) return json({ error: idCheck.error }, 400);
  if (!body.word?.trim() || body.grade == null) return json({ error: "word and grade required" }, 400);
  const word = body.word.trim();
  const grade = Math.max(0, Math.min(5, parseInt(body.grade, 10)));
  const srsRaw = await env.NET_PET_KV.get(`srs_data_${studentId}`);
  const srsMap = srsRaw ? JSON.parse(srsRaw) : {};
  const existing = srsMap[word] || { word, interval: 1, repetitions: 0, ease_factor: 2.5, next_review: 0 };
  srsMap[word] = { ...existing, ...computeNextReview(existing, grade), word };
  await env.NET_PET_KV.put(`srs_data_${studentId}`, JSON.stringify(srsMap));
  return json({ ok: true, word, nextReview: srsMap[word].next_review });
}
```

